// 2. FALLBACK SACRED ARTWORK & PROMPTPAY 9 THB QR PLACEHOLDER SVG
// ============================================================================

function createSacredSceneSvg({ title, subtitle, theme = 'gold', tag = 'ภาพอ้างอิงสถานที่มูเตลู' }) {
  const palettes = {
    gold: { bg1: '#7C2D12', bg2: '#B45309', bg3: '#D97706', accent: '#FEF08A', glow: '#FFFBEB' },
    naga: { bg1: '#065F46', bg2: '#047857', bg3: '#0D9488', accent: '#A7F3D0', glow: '#ECFDF5' },
    hindu: { bg1: '#831843', bg2: '#BE185D', bg3: '#E11D48', accent: '#FBCFE8', glow: '#FFF1F2' },
    wessuwan: { bg1: '#7F1D1D', bg2: '#B91C1C', bg3: '#D97706', accent: '#FDE047', glow: '#FEF9C3' },
    buddha: { bg1: '#1E3A8A', bg2: '#1D4ED8', bg3: '#D97706', accent: '#FDE047', glow: '#FFFBEB' },
    crowd: { bg1: '#0369A1', bg2: '#0284C7', bg3: '#0EA5E9', accent: '#E0F2FE', glow: '#F0F9FF' }
  };
  const pal = palettes[theme] || palettes.gold;

  const svg = `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 640 340">
    <defs>
      <linearGradient id="bg" x1="0%" y1="0%" x2="100%" y2="100%">
        <stop offset="0%" stop-color="${pal.bg1}" />
        <stop offset="55%" stop-color="${pal.bg2}" />
        <stop offset="100%" stop-color="${pal.bg3}" />
      </linearGradient>
      <linearGradient id="goldGrad" x1="0%" y1="0%" x2="0%" y2="100%">
        <stop offset="0%" stop-color="#FFFBEB" />
        <stop offset="50%" stop-color="#FDE047" />
        <stop offset="100%" stop-color="#F59E0B" />
      </linearGradient>
    </defs>
    <rect width="640" height="340" fill="url(#bg)" />
    <circle cx="320" cy="140" r="88" fill="${pal.accent}" fill-opacity="0.22" />
    <circle cx="320" cy="140" r="64" fill="none" stroke="${pal.glow}" stroke-width="1.8" stroke-dasharray="5 5" />
    <path d="M320,42 L338,105 L364,165 L388,215 L252,215 L276,165 L302,105 Z" fill="url(#goldGrad)" stroke="${pal.glow}" stroke-width="2" />
    <rect x="230" y="215" width="180" height="16" rx="5" fill="#FDE047" />
    <rect x="20" y="18" width="210" height="32" rx="16" fill="#451A03" fill-opacity="0.7" stroke="${pal.accent}" stroke-width="1.5" />
    <text x="125" y="39" text-anchor="middle" fill="${pal.glow}" font-family="sans-serif" font-size="13" font-weight="bold">${tag}</text>
    <rect x="0" y="248" width="640" height="92" fill="#451A03" fill-opacity="0.82" />
    <text x="28" y="284" fill="#FEF08A" font-family="sans-serif" font-size="22" font-weight="bold">${title}</text>
    <text x="28" y="314" fill="#FFFBEB" font-family="sans-serif" font-size="15">${subtitle}</text>
  </svg>`;

  return `data:image/svg+xml;utf8,${encodeURIComponent(svg)}`;
}

