function getGoogleMapsNavUrl(place, provinceName = '') {
  const nameToUse = place?.rawNameTh || place?.nameTh || '';
  const query = encodeURIComponent(`${nameToUse} ${provinceName}`.trim());
  if (place?.lat && place?.lng) {
    return `https://www.google.com/maps/dir/?api=1&destination=${place.lat},${place.lng}&destination_place_id=${query}&travelmode=driving`;
  }
  return `https://www.google.com/maps/dir/?api=1&destination=${query}&travelmode=driving`;
}

function getGoogleMapsSearchUrl(place, provinceName = '') {
  const nameToUse = place?.rawNameTh || place?.nameTh || '';
  const query = encodeURIComponent(`${nameToUse} ${provinceName}`.trim());
  return `https://www.google.com/maps/search/?api=1&query=${query}`;
}

