function localizePlaceItem(place, lang, rawProvNameTh = '') {
  if (!place) return place;
  const rawNameTh = place.rawNameTh || place.nameTh;
  if (lang === 'th') {
    return { ...place, rawNameTh };
  }
  const trData = PLACE_FULL_I18N[place.id]?.[lang];
  const provI18n = PROVINCE_I18N[place.provinceId];
  const localizedProvName = provI18n ? provI18n[lang] : (place.provinceName || rawProvNameTh);
  if (trData) {
    return {
      ...place,
      rawNameTh,
      nameTh: trData.name,
      deity: trData.deity,
      socialBadge: trData.socialBadge,
      parkingStatus: trData.parkingStatus,
      bestTime: trData.bestTime,
      offerings: trData.offerings,
      chant: trData.chant,
      secretTip: trData.secretTip,
      ritualSteps: trData.steps,
      provinceName: localizedProvName,
      photoCredit:
        lang === 'zh'
          ? `实景拍摄照片：${trData.name} (Wikimedia Commons)`
          : `Real Location Photo: ${trData.name} (Wikimedia Commons)`
    };
  }
  // Fallback for dynamically added places from Wikipedia
  return {
    ...place,
    rawNameTh,
    nameTh: lang === 'en' ? (place.nameEn || place.nameTh) : place.nameTh,
    provinceName: localizedProvName,
    socialBadge:
      lang === 'zh'
        ? '🔥 发现自 TikTok / Facebook / YouTube 热门趋势'
        : '🔥 Discovered from TikTok / Facebook / YouTube Trends',
    parkingStatus:
      lang === 'zh'
        ? '寺庙院内及周边设有停车区（可通过 Google 地图查看实时路线）'
        : 'Temple parking and nearby lots available (check live route on Google Maps)',
    bestTime: lang === 'zh' ? '07:30 - 17:30（建议上午参拜）' : '07:30 AM - 05:30 PM',
    offerings:
      lang === 'zh'
        ? '鲜花、香烛与新鲜花环'
        : 'Fresh flowers, incense, candles, and garlands',
    photoCredit:
      lang === 'zh'
        ? `实景参考照片：${place.nameEn || place.nameTh}`
        : `Location Photo: ${place.nameEn || place.nameTh}`
  };
}

function localizeProvinceItem(prov, lang) {
  if (!prov) return prov;
  const rawNameTh = prov.rawNameTh || prov.nameTh;
  if (lang === 'th') {
    return {
      ...prov,
      rawNameTh,
      places: prov.places.map((pl) => localizePlaceItem(pl, 'th', rawNameTh))
    };
  }
  const pTr = PROVINCE_I18N[prov.id];
  const locName = pTr ? pTr[lang] : (prov.nameEn || prov.nameTh);
  const locMotto = pTr ? (lang === 'zh' ? pTr.mottoZh : pTr.mottoEn) : prov.motto;
  const locDeity = pTr ? (lang === 'zh' ? pTr.deityZh : pTr.deityEn) : prov.topDeity;
  const locWindow = pTr ? (lang === 'zh' ? pTr.windowZh : pTr.windowEn) : prov.bestWindow;
  return {
    ...prov,
    rawNameTh,
    nameTh: locName,
    motto: locMotto,
    topDeity: locDeity,
    bestWindow: locWindow,
    places: prov.places.map((pl) => localizePlaceItem({ ...pl, provinceId: prov.id }, lang, rawNameTh))
  };
}

function localizeWhisperItem(w, lang) {
  if (!w) return w;
  if (lang === 'th') return w;
  const wTr = WHISPER_FULL_I18N[w.id]?.[lang];
  const pTr = PROVINCE_I18N[w.provinceId];
  const plTr = PLACE_FULL_I18N[w.placeId]?.[lang];
  return {
    ...w,
    provinceName: pTr ? pTr[lang] : w.provinceName,
    placeName: plTr ? plTr.name : w.placeName,
    author: wTr ? wTr.author : (lang === 'zh' ? `${w.author} (实时分享)` : `${w.author} (Live)`),
    avatarBadge: wTr ? wTr.avatarBadge : (lang === 'zh' ? '📸 现场善信分享' : '📸 Live Visitor'),
    timeAgo: wTr ? wTr.timeAgo : (lang === 'zh' ? '刚刚更新' : 'Just now'),
    text: wTr ? wTr.text : w.text
  };
}

