function getLocalizedProvinceName(prov, lang) {
  if (!prov) return '';
  const item = PROVINCE_I18N[prov.id];
  if (!item) return lang === 'en' ? (prov.nameEn || prov.nameTh) : prov.nameTh;
  return item[lang] || prov.nameTh;
}

function getLocalizedProvinceMotto(prov, lang) {
  if (!prov) return '';
  const item = PROVINCE_I18N[prov.id];
  if (!item) return prov.motto;
  if (lang === 'en') return item.mottoEn;
  if (lang === 'zh') return item.mottoZh;
  return item.mottoTh;
}

function getLocalizedProvinceDeity(prov, lang) {
  if (!prov) return '';
  const item = PROVINCE_I18N[prov.id];
  if (!item) return prov.topDeity;
  if (lang === 'en') return item.deityEn;
  if (lang === 'zh') return item.deityZh;
  return item.deityTh;
}

function getLocalizedPlaceName(place, lang) {
  if (!place) return '';
  if (lang === 'th') return place.nameTh;
  const trData = PLACE_FULL_I18N[place.id]?.[lang];
  if (trData?.name) return trData.name;
  if (lang === 'en') return place.nameEn || place.nameTh;
  return place.nameTh;
}

