  // Automatically fetch exact real photos from Thai Wikipedia MediaWiki API on mount
  useEffect(() => {
    let isMounted = true;
    async function fetchRealWikipediaPhotos() {
      const titlesToFetch = [];
      INITIAL_PROVINCES_DATA.forEach((prov) => {
        prov.places.forEach((pl) => {
          if (pl.wikiTitle) titlesToFetch.push(pl.wikiTitle);
        });
      });
      if (titlesToFetch.length === 0) return;

      try {
        const url = `https://th.wikipedia.org/w/api.php?action=query&format=json&origin=*&prop=pageimages&piprop=original|thumbnail&pithumbsize=960&titles=${encodeURIComponent(
          titlesToFetch.join('|')
        )}`;
        const resp = await fetch(url);
        if (!resp.ok) return;
        const data = await resp.json();
        const pages = data?.query?.pages;
        if (!pages || !isMounted) return;

        const titleToImage = {};
        Object.values(pages).forEach((pg) => {
          const img = pg?.original?.source || pg?.thumbnail?.source;
          if (pg?.title && img) {
            titleToImage[pg.title] = img;
          }
        });

        if (Object.keys(titleToImage).length > 0) {
          setProvincesData((prev) =>
            prev.map((prov) => ({
              ...prov,
              places: prov.places.map((pl) =>
                pl.wikiTitle && titleToImage[pl.wikiTitle]
                  ? {
                      ...pl,
                      image: titleToImage[pl.wikiTitle],
                      photoCredit: `ภาพถ่ายสถานที่จริง: ${pl.nameTh} (Wikipedia Thailand)`
                    }
                  : pl
              )
            }))
          );
        }
      } catch (e) {
        // Keeps the pre-populated Wikimedia Commons URLs
      }
    }
    fetchRealWikipediaPhotos();
    return () => {
      isMounted = false;
    };
  }, []);

